import{_ as o,c as a,o as i,ae as c}from"./chunks/framework.DEXG3EuZ.js";const h=JSON.parse('{"title":"从 v1 迁移到 v2","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migration-v2.md","filePath":"guide/migration-v2.md","lastUpdated":1792605191000}'),d={name:"guide/migration-v2.md"};function l(t,e,r,n,s,p){return i(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="从-v1-迁移到-v2" tabindex="-1">从 v1 迁移到 v2 <a class="header-anchor" href="#从-v1-迁移到-v2" aria-label="Permalink to &quot;从 v1 迁移到 v2&quot;">​</a></h1><h2 id="breaking-changes" tabindex="-1">Breaking Changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking Changes&quot;">​</a></h2><ul><li>Node.js 最低版本改为 22.12，构建升级到 Vite 8 / Rolldown。</li><li>登录 endpoint 从 <code>/api/login</code> 改为 <code>/api/auth/login</code>。</li><li>请求入口改为 <code>src/api/client.ts</code> + <code>src/api/modules</code>；旧 <code>utils/request</code> 只保留兼容 re-export。</li><li><code>VITE_USE_PWA</code> 改为 <code>VITE_PWA_ENABLED</code>。</li><li>UI 由三套 resolver 同开改为 <code>VITE_UI_FRAMEWORK</code> 单选。</li><li>Token 持久化从 <code>localStorage</code> 改为 <code>sessionStorage</code>。</li><li>主导航和 route names 重构为 Home / Examples / AI / Member。</li></ul><h2 id="迁移步骤" tabindex="-1">迁移步骤 <a class="header-anchor" href="#迁移步骤" aria-label="Permalink to &quot;迁移步骤&quot;">​</a></h2><ol><li>升级 Node/pnpm 并重新执行 <code>pnpm install</code>。</li><li>对照 <code>.env.example</code> 迁移环境变量，明确 UI 框架。</li><li>将页面 Axios 调用移动到 <code>src/api/modules</code>，使用 <code>ApiError</code>。</li><li>将远程列表/详情从 Pinia 移至 TanStack Query。</li><li>替换 <code>openapi/schema.yaml</code> 并运行 <code>pnpm api:generate</code>。</li><li>将产品 SVG 放入 <code>src/assets/icons</code> 并扩展 <code>SvgIconName</code>。</li><li>检查自定义路由 meta、权限和登录 redirect。</li><li>运行 <code>pnpm check</code> 与关键 <code>pnpm test:e2e</code>。</li></ol><h2 id="未恢复的旧实现" tabindex="-1">未恢复的旧实现 <a class="header-anchor" href="#未恢复的旧实现" aria-label="Permalink to &quot;未恢复的旧实现&quot;">​</a></h2><p>旧 <code>vite-plugin-pages</code> 没有恢复，因为隐式路由在当前规模收益不足。旧 imagemin 二进制链替换为 Sharp/SVGO。旧 iconfont 被 SVG Sprite 取代。QRCode/restart 插件因 Vite 8 peer incompatibility 移除；Vite 自身会重载配置，设备调试可使用终端局域网 URL 或后续 CLI。</p>',7)])])}const _=o(d,[["render",l]]);export{h as __pageData,_ as default};
